const SB_URL='https://vooersreyxuidtsxncsv.supabase.co',SB_KEY='sb_publishable_j8hbFbLZveBkjZ1VwrX3-g_tlM1pBLB';
let sbSession=JSON.parse(localStorage.getItem('buzzo_session')||'null'),sbAdmin=false,sbProfile=null;
const escHtml=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
async function api(path,options={}){const headers={'apikey':SB_KEY,'Content-Type':'application/json',...(sbSession?.access_token?{'Authorization':'Bearer '+sbSession.access_token}:{}),...options.headers};const r=await fetch(SB_URL+path,{...options,headers});let d=await r.json().catch(()=>null);if(!r.ok)throw Error(d?.msg||d?.message||d?.error_description||d?.error||'Permintaan gagal');return d}
async function refreshSession(){if(!sbSession)return;try{if(sbSession.expires_at*1000<Date.now()+60000){const v=await api('/auth/v1/token?grant_type=refresh_token',{method:'POST',body:JSON.stringify({refresh_token:sbSession.refresh_token})});sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v))}sbAdmin=await api('/rest/v1/rpc/jjta_is_admin',{method:'POST',body:'{}'});if(!sbAdmin){const p=await api('/rest/v1/jjta_profiles?select=*');sbProfile=p[0]||null}updateAccountButton()}catch(e){sbSession=null;localStorage.removeItem('buzzo_session');updateAccountButton()}}
function updateAccountButton(){let el=document.getElementById('account-entry');if(!el){el=document.createElement('button');el.id='account-entry';el.className='account-entry';document.querySelector('body>header').appendChild(el)}el.textContent=sbSession?(sbAdmin?'Dashboard admin':'Portal member'):'Login / Daftar';el.onclick=()=>sbSession?portal():showAuth('login')}
const authBox=()=>document.getElementById('auth-screen');let signupDraft={};
showAuth=function(type){closeModal();const box=authBox();box.hidden=false;document.body.classList.add('auth-open');let login=type==='login';box.innerHTML=`<header><button class="action" data-sb-close>← Kembali</button><strong>BUZZO · ${login?'LOGIN':'PENDAFTARAN'}</strong></header><div class="auth-grid"><section><small>PORTAL MEMBER</small><h1>${login?'Selamat datang kembali.':'Registrasi, hubungkan akun, bertumbuh.'}</h1><p>Kelola profil bisnis, manfaat, dan pengajuan konsultasi dalam satu tempat.</p></section><section class="auth-form"><h2>${login?'Masuk ke akun':'Daftar program'}</h2>${login?`<form id="sb-login"><label>Email<input name="email" type="email" required autocomplete="email"></label><label>Password<input name="password" type="password" required autocomplete="current-password"></label><button class="cta">Login</button><p class="sb-message" role="status"></p></form><p>Belum punya akun? <button class="action" data-sb-register>Daftar</button></p>`:`<form id="sb-register"><label>Kode undangan<input name="invite_code" required placeholder="Kode undangan"></label><label>Nama bisnis<input name="business_name" required></label><label>Advertiser ID<input name="advertiser_id" required></label><label>Nama toko TikTok Shop<input name="shop_name" required></label><label>Link TikTok Shop<input name="shop_url" type="url" required></label><label>Shop Code<input name="shop_code" required></label><label>Nama lengkap<input name="full_name" required></label><label>Nomor WhatsApp<input name="whatsapp" type="tel" required></label><label>Email<input name="email" type="email" required></label><label>Password<input name="password" type="password" minlength="8" required></label><label>Konfirmasi password<input name="password_confirm" type="password" minlength="8" required></label><label>Tertarik layanan Buzzo?<select name="agency_interest"><option>Belum yakin</option><option>Ya</option><option>Tidak</option></select></label><button class="cta">Daftar</button><p class="sb-message" role="status"></p></form><p>Sudah punya akun? <button class="action" data-sb-login>Login</button></p>`}</section></div>`;window.scrollTo(0,0)};
async function portal(view='summary'){if(!sbSession){showAuth('login');return}const box=authBox();box.hidden=false;document.body.classList.add('auth-open');box.innerHTML=`<header><button class="action" data-sb-close>← Kembali ke web</button><strong>BUZZO · ${sbAdmin?'ADMIN':'PORTAL MEMBER'}</strong><button class="action" data-sb-logout>Keluar</button></header><div class="sb-portal"><nav><button class="action" data-sb-view="summary">Ringkasan</button>${sbAdmin?'<button class="action" data-sb-view="registrations">Pendaftaran</button><button class="action" data-sb-view="consultations">Konsultasi</button>':'<button class="action" data-sb-view="benefits">Manfaat</button><button class="action" data-sb-view="consultations">Konsultasi VIP</button>'}</nav><main id="sb-portal-content"><p>Memuat…</p></main></div>`;window.scrollTo(0,0);const target=document.getElementById('sb-portal-content');try{if(sbAdmin){if(view==='consultations'){let [items,profiles]=await Promise.all([api('/rest/v1/jjta_consultations?select=*&order=created_at.desc'),api('/rest/v1/jjta_profiles?select=user_id,full_name,business_name,email')]);target.innerHTML='<h1>Pengajuan konsultasi</h1>'+ (items.length?items.map(x=>{let p=profiles.find(y=>y.user_id===x.user_id)||{};return `<article class="modal-card"><strong>${escHtml(p.full_name)} · ${escHtml(p.business_name)}</strong><p>${escHtml(p.email)} · ${escHtml(x.status)}</p><p>${escHtml(x.requested_date)} · ${escHtml(x.requested_time)} WIB</p><p>${escHtml(x.goals)}</p></article>`}).join(''):'<p>Belum ada pengajuan.</p>')}else{let p=await api('/rest/v1/jjta_profiles?select=*&order=created_at.desc');target.innerHTML=`<h1>${view==='summary'?'Dashboard admin':'Pendaftaran'}</h1><p>${p.length} pendaftar</p>`+(p.length?p.map(x=>`<article class="modal-card"><h3>${escHtml(x.full_name)} · ${escHtml(x.business_name)}</h3><p>${escHtml(x.email)} · ${escHtml(x.whatsapp)}</p><p>Advertiser ID: ${escHtml(x.advertiser_id)} · Shop Code: ${escHtml(x.shop_code)}</p><p>Toko: ${escHtml(x.shop_name)} · ${escHtml(x.shop_url)}</p><p>Layanan Buzzo: ${escHtml(x.agency_interest)}</p><p>Minat program: ${escHtml((x.interests||[]).join(', ')||'—')}</p><label>Level terverifikasi <select data-sb-level="${x.user_id}">${[1,2,3,4,5].map(n=>`<option value="${n}" ${n===x.verified_level?'selected':''}>Level ${n}</option>`).join('')}</select></label></article>`).join(''):'<p>Belum ada pendaftar.</p>')}}else{let p=await api('/rest/v1/jjta_profiles?select=*');sbProfile=p[0];if(!sbProfile){target.innerHTML='<h1>Profil belum tersedia</h1><p>Hubungi admin Buzzo.</p>';return}let level=sbProfile.verified_level,cadence=['','','1 kali per bulan','setiap 2 minggu','setiap minggu','setiap minggu'];if(view==='consultations'){let list=await api('/rest/v1/jjta_consultations?select=*&order=created_at.desc');target.innerHTML=`<h1>Konsultasi VIP</h1><p>${level>=2?'Frekuensi: '+cadence[level]:'Tersedia mulai Level 2 setelah diverifikasi admin.'}</p>${level>=2?`<form id="sb-consult"><label>Tanggal · WIB<input type="date" name="requested_date" required></label><label>Waktu · WIB<input type="time" name="requested_time" required></label><label>Tujuan dan kendala<textarea name="goals" required></textarea></label><button class="cta">Kirim pengajuan</button><p class="sb-message" role="status"></p></form>`:''}<h2>Riwayat pengajuan</h2>`+(list.length?list.map(x=>`<article class="modal-card"><strong>${escHtml(x.requested_date)} · ${escHtml(x.requested_time)} WIB</strong><p>${escHtml(x.status)}</p><p>${escHtml(x.goals)}</p></article>`).join(''):'<p>Belum ada pengajuan.</p>')}else{target.innerHTML=`<small>RINGKASAN</small><h1>Halo, ${escHtml(sbProfile.full_name)}.</h1><p>Kelola progres brand dan manfaat Buzzo kamu.</p><article class="modal-card"><h2>Level ${level} · ${namesForLevel[level-1]}</h2><p>Level ditetapkan admin setelah verifikasi spending 30 hari terakhir.</p><p>${escHtml(requirementsForLevel[level-1])}</p>${level>=2?`<p>Konsultasi VIP: ${cadence[level]}</p>`:''}</article><h2>Manfaat untukmu</h2>${benefitRows.filter(x=>!x.displayLevel && x.level<=level && (!x.id.startsWith('Konsultasi VIP')||x.level===level)).map(x=>`<article class="modal-card"><strong>${escHtml(x.title)}</strong><p>${escHtml(x.description)}</p></article>`).join('')}<article class="modal-card"><h3>Profil toko</h3><p>${escHtml(sbProfile.business_name)} · ${escHtml(sbProfile.shop_name)}</p><p>Advertiser ID: ${escHtml(sbProfile.advertiser_id)} · Shop Code: ${escHtml(sbProfile.shop_code)}</p></article>`}}}catch(e){target.innerHTML='<p>Gagal memuat data: '+escHtml(e.message)+'</p>'}}
document.addEventListener('click',e=>{let b=e.target.closest('button');if(!b)return;if(b.matches('[data-sb-close]')){authBox().hidden=true;document.body.classList.remove('auth-open');return}if(b.matches('[data-sb-register]')){showAuth('register');return}if(b.matches('[data-sb-login]')){showAuth('login');return}if(b.matches('[data-sb-logout]')){sbSession=null;sbAdmin=false;sbProfile=null;localStorage.removeItem('buzzo_session');authBox().hidden=true;document.body.classList.remove('auth-open');updateAccountButton();return}if(b.dataset.sbView){portal(b.dataset.sbView);return}if(b.hasAttribute('data-sb-consult')){closeModal();portal('consultations');return}},true);
document.addEventListener('change',async e=>{let el=e.target.closest('[data-sb-level]');if(!el)return;try{await api('/rest/v1/jjta_profiles?user_id=eq.'+encodeURIComponent(el.dataset.sbLevel),{method:'PATCH',headers:{Prefer:'return=representation'},body:JSON.stringify({verified_level:Number(el.value)})});el.parentElement.insertAdjacentHTML('beforeend','<small> Tersimpan</small>')}catch(err){alert('Gagal menyimpan level: '+err.message)}},true);
document.addEventListener('submit',async e=>{let f=e.target;if(!['sb-login','sb-register','sb-consult'].includes(f.id))return;e.preventDefault();e.stopImmediatePropagation();let message=f.querySelector('.sb-message'),button=f.querySelector('button[type=submit],button:not([type])');if(button)button.disabled=true;message.textContent='Memproses…';try{let d=Object.fromEntries(new FormData(f));if(f.id==='sb-login'){let v=await api('/auth/v1/token?grant_type=password',{method:'POST',body:JSON.stringify({email:d.email,password:d.password})});sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v));await refreshSession();await portal()}else if(f.id==='sb-register'){if(d.invite_code.trim().toUpperCase()!=='JAKARTANOV')throw Error('Kode undangan tidak valid.');if(d.password!==d.password_confirm)throw Error('Konfirmasi password belum cocok.');let {email,password,password_confirm,...metadata}=d;metadata.interests=JSON.parse(metadata.interests||'[]');let v=await api('/auth/v1/signup',{method:'POST',body:JSON.stringify({email,password,data:metadata})});if(v.access_token){sbSession=v;localStorage.setItem('buzzo_session',JSON.stringify(v));await refreshSession();await portal()}else{f.reset();message.textContent='Pendaftaran diterima. Cek email untuk verifikasi, lalu login.'}}else{await api('/rest/v1/jjta_consultations',{method:'POST',headers:{Prefer:'return=minimal'},body:JSON.stringify({...d,user_id:sbSession.user.id})});await portal('consultations')}}catch(err){message.textContent='Gagal: '+err.message}finally{if(button)button.disabled=false}},true);
const originalBenefitBody=bodyFor;bodyFor=function(id){if(/^Konsultasi VIP Level [2-5]$/.test(id)){const n=Number(id.slice(-1)),frequency=['','','1 kali per bulan','setiap 2 minggu','setiap minggu','setiap minggu'];return `<p>Review, evaluasi, dan optimasi TikTok Ads, TikTok Shop, serta TikTok One.</p><div class="modal-card"><h3>Konsultasi VIP Level ${n}</h3><p>Frekuensi: ${frequency[n]}. Frekuensi mengikuti level tertinggi yang diverifikasi admin.</p><p>Login dan buka portal member untuk mengirim pengajuan konsultasi. Akses mulai Level 2 setelah verifikasi admin.</p><button type="button" class="action" data-sb-consult>${sbSession?'Buka konsultasi':'Login untuk mengajukan'}</button></div>`}return originalBenefitBody(id)};
updateAccountButton();refreshSession();
